"""Explicit small arguments with visible stopping boundaries, not formal verification."""
import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]/'dist'
nodes=[];edges=[]
def add(key,title,assumptions,conclusion,why,deps=(),role='Derived step',status='Elementary argument · not machine checked'):
 id='reason:deep:'+key
 nodes.append(dict(id=id,kind='Argument',title=title,summary=conclusion,assumptions=assumptions,conclusion=conclusion,justification=why,status=status,boundary=role,extraction='Curated logical decomposition. All outgoing Requires result premises are needed together. Definitions and unexpanded theorem or research boundaries are labeled explicitly.'))
 for d in deps:edges.append(dict(source=id,target='reason:deep:'+d,type='USES_RESULT',evidence='Required justification in this curated argument; mathematical assumptions must also be satisfied.'))
 return id
def link(a,key):edges.append(dict(source=a,target='reason:deep:'+key,type='HAS_ARGUMENT',evidence='Detailed elementary argument or explicitly conditional source reconstruction.'))
def base(key,title,assumptions,conclusion,why,role='Definition'):
 return add(key,title,assumptions,conclusion,why,role=role,status=role+' · stopping boundary')
base('rational-def','What “rational” means',['b is a nonzero integer.'],'a/b is rational for every integer a.','This is the definition of ℚ; equality identifies fractions a/b and c/d when ad=bc. It is a definition, not a theorem about a particular constant.')
base('integer-arithmetic','Integer arithmetic rules',['a,b,c are integers.'],'Sums, products and negatives are integers; products of nonzero integers are nonzero.','These elementary integer facts are accepted at this boundary. A construction from natural numbers would need the corresponding induction and order arguments.','Standard arithmetic boundary')
add('rational-add','Why adding rationals stays rational',['x=a/b and y=c/d with integer a,b,c,d and b,d≠0.'],'x+y=(ad+bc)/(bd) is rational.','Integer arithmetic puts ad+bc and bd in ℤ and bd≠0. The displayed fraction therefore satisfies the definition of rational.',['rational-def','integer-arithmetic'])
add('rational-product','Why multiplying rationals stays rational',['x=a/b and y=c/d with integer a,b,c,d and b,d≠0.'],'xy=ac/(bd) and −x=(−a)/b are rational.','The numerators are integers; the denominators remain nonzero. Apply the definition of ℚ.',['rational-def','integer-arithmetic'])
base('induction','The induction principle',['P(n) is a proposition about positive integers.'],'P(1) and ∀n≥1(P(n)⇒P(n+1)) imply ∀n≥1 P(n).','Induction is a foundational principle of the natural numbers. It cannot be replaced by checking finitely many examples.','Foundational principle')
add('finite-rational','Why any finite sum or product of rationals is rational',['There are finitely many rational terms.'],'Their sum and product are rational.','For one term this is immediate. Adding or multiplying one more rational preserves rationality by the two closure lemmas. Induction handles any positive number of terms. The empty sum 0 and empty product 1 are rational by definition.',['rational-add','rational-product','induction'])
base('det-def','Determinant as a finite signed sum',['A is an n×n matrix and n≥1.'],'det A=Σσ sign(σ)∏ᵢAᵢ,σ(i), over permutations σ of {1,…,n}.','This Leibniz formula can be used to define the determinant. There are finitely many permutations and every sign is +1 or −1.')
add('rational-det','Why rational matrix entries give a rational determinant',['Every entry of a finite square matrix A is rational.'],'det A is rational.','Each product in the determinant formula is rational. Multiplying by its integer sign preserves rationality, and the finite sum remains rational. No invertibility assumption is needed: zero determinants are rational too.',['det-def','finite-rational'])
link('college:determinants','rational-det');link('reason:rational','rational-det')
base('factorization','Unique prime factorization of a rational',['q is a nonzero rational.'],'q=±∏p p^eₚ, with integer eₚ and finite support.','Factor the nonzero numerator and denominator into primes and subtract their exponents. This uses the fundamental theorem of arithmetic, whose proof is not expanded here.','Standard theorem boundary')
base('valuation-def','Define a prime valuation and prime absolute value',['q≠0 is rational and p is prime.'],'v_p(q)=eₚ and |q|_p=p^(−eₚ).','Here eₚ is the exponent in the prime factorization. If valuation is extended to zero, use v_p(0)=+∞; |0|_p=0. The nonzero product formula does not apply to zero.')
add('finite-cancellation','Cancel matching prime powers',['Only finitely many integers eₚ are nonzero.'],'(∏p p^eₚ)(∏p p^(−eₚ))=1.','Because the products are finite, regroup each p^eₚ with p^(−eₚ). Each pair equals p⁰=1. There is no interchange of an infinite product or limit.',['integer-arithmetic'])
add('product-formula','Derive the rational product formula',['q is a nonzero rational.'],'|q|∞∏p|q|_p=1.','Prime factorization gives |q|∞=∏p p^eₚ; the prime absolute values give the reciprocal factors. Finite cancellation proves the identity. Estimating individual factors for a research construction is a separate task.',['factorization','valuation-def','finite-cancellation'])
link('college:product','product-formula')
